edits.new:
code{font:.85rem Consolas,"Courier New",monospace;border:1px solid var(--tinta);padding:1px 4px}
code{white-space:nowrap}
@media(max-width:620px){table,tbody,tr,td{display:block;width:auto}thead{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}tr{border-top:2px solid var(--tinta)}td[data-label]::before{content:attr(data-label) ": ";font-weight:700}}
